  "next_cursor": "eyJvZmZzZXQiOjIwfQ",
  "has_more": true
&#125;}}

<h2 id="errors">Error shape</h2>
{{ds:component/code-block|filename=error-response.json|language=json|code=&#123;
  "error": &#123;
    "code": "connector_unauthorized",
    "message": "The connector's credentials were rejected by the source system.",
    "request_id": "req_c93a10"
  &#125;
&#125;}}

{{ds:component/alert|variant=danger|title=Breaking change from v1|body_html=<p>v1 returned bare error strings. v2 always wraps errors in an <code>error</code> object with a stable <code>code</code> field — match on <code>code</code>, not on <code>message</code> text.</p>}}

